def run_react_loop(user_task, tools, model_call, max_steps=8):
    transcript = [{"role": "user", "content": user_task}]
    for step in range(max_steps):
        response = model_call(transcript)  # model returns {"thought": ..., "action": ..., "action_input": ...} or {"final_answer": ...}

        if "final_answer" in response:
            return {"status": "completed", "answer": response["final_answer"], "steps_used": step + 1}

        tool_name = response["action"]
        tool_input = response["action_input"]
        if tool_name not in tools:
            observation = f"Error: tool '{tool_name}' does not exist."
        else:
            try:
                observation = tools[tool_name](tool_input)
            except Exception as e:
                observation = f"Error executing tool: {str(e)}"

        transcript.append({"role": "assistant", "content": response})
        transcript.append({"role": "tool_result", "name": tool_name, "content": observation})

    # Max steps reached without a final answer: stop, don't loop forever
    return {
        "status": "max_steps_exceeded",
        "answer": None,
        "steps_used": max_steps,
        "note": "Agent did not converge; escalate for human review rather than retry indefinitely.",
    }

HIGH_STAKES_TOOLS = {"issue_refund", "send_email_to_customer", "cancel_subscription", "delete_record"}

def execute_tool_call(tool_name, tool_input, agent_session_id):
    if tool_name not in HIGH_STAKES_TOOLS:
        return tools[tool_name](tool_input)

    approval_request = create_approval_request(
        session_id=agent_session_id,
        tool_name=tool_name,
        tool_input=tool_input,
        requested_at=now(),
        status="pending",
    )
    notify_approver(approval_request)

    decision = wait_for_approval(approval_request.id, timeout_seconds=1800)

    if decision.status == "approved":
        log_audit_event(approval_request.id, "approved", decision.approver_id)
        return tools[tool_name](tool_input)

    if decision.status == "rejected":
        log_audit_event(approval_request.id, "rejected", decision.approver_id)
        return {"status": "rejected", "reason": decision.reason or "No reason provided"}

    # Timed out waiting for a human decision: fail closed, never default to executing
    log_audit_event(approval_request.id, "timed_out", approver_id=None)
    return {"status": "timed_out", "note": "No human response within 30 minutes; action was NOT executed."}

import re

def chunk_by_headings(markdown_text, source_doc_id, max_chunk_chars=1200):
    # Split on markdown headings (##, ###, etc.), keeping the heading with its section
    sections = re.split(r"(?=^#{1,4}\s)", markdown_text, flags=re.MULTILINE)
    chunks = []

    for section in sections:
        section = section.strip()
        if not section:
            continue

        heading_match = re.match(r"^(#{1,4})\s+(.*)", section)
        heading = heading_match.group(2).strip() if heading_match else "Untitled Section"
        body = section[heading_match.end():].strip() if heading_match else section

        if len(body) <= max_chunk_chars:
            chunks.append({
                "text": body,
                "source_doc_id": source_doc_id,
                "section_heading": heading,
            })
        else:
            # Section too long for one chunk: split further on paragraph boundaries,
            # still tagging every sub-chunk with the same parent heading
            paragraphs = body.split("\n\n")
            current = ""
            for para in paragraphs:
                if len(current) + len(para) > max_chunk_chars and current:
                    chunks.append({"text": current.strip(), "source_doc_id": source_doc_id, "section_heading": heading})
                    current = para
                else:
                    current += "\n\n" + para
            if current.strip():
                chunks.append({"text": current.strip(), "source_doc_id": source_doc_id, "section_heading": heading})

    return chunks

import time
import functools

MODEL_PRICING_PER_1K_TOKENS = {
    "gpt-4o": {"input": 0.0025, "output": 0.010},
    "gpt-4o-mini": {"input": 0.00015, "output": 0.0006},
}

def track_llm_call(model_name):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            start = time.monotonic()
            try:
                response = fn(*args, **kwargs)
                status = "success"
            except Exception as e:
                latency_ms = (time.monotonic() - start) * 1000
                log_llm_call_metric(model_name, status="error", error=str(e), latency_ms=latency_ms, cost_usd=None)
                raise

            latency_ms = (time.monotonic() - start) * 1000
            usage = response.usage
            pricing = MODEL_PRICING_PER_1K_TOKENS.get(model_name)
            cost_usd = None
            if pricing:
                cost_usd = (
                    (usage.prompt_tokens / 1000) * pricing["input"]
                    + (usage.completion_tokens / 1000) * pricing["output"]
                )

            log_llm_call_metric(
                model_name,
                status=status,
                latency_ms=latency_ms,
                prompt_tokens=usage.prompt_tokens,
                completion_tokens=usage.completion_tokens,
                cost_usd=cost_usd,
            )
            return response
        return wrapper
    return decorator

@track_llm_call(model_name="gpt-4o")
def call_model(messages):
    return openai_client.chat.completions.create(model="gpt-4o-deployment", messages=messages)

