import sqlparse

ALLOWED_STATEMENT_TYPES = {"SELECT"}
FORBIDDEN_KEYWORDS = {"DROP", "DELETE", "UPDATE", "INSERT", "ALTER", "TRUNCATE", "GRANT", "EXEC"}
ROW_LIMIT = 500

def generate_and_run_sql(question, schema_description, readonly_db_connection):
    generated_sql = model_call(
        f"Given this schema:\n{schema_description}\n\nWrite a single SELECT statement to answer: {question}\n"
        f"Return only the SQL, no explanation."
    )

    parsed = sqlparse.parse(generated_sql.strip())
    if len(parsed) != 1:
        return {"status": "rejected", "reason": "Exactly one SQL statement is required."}

    statement = parsed[0]
    statement_type = statement.get_type()
    if statement_type not in ALLOWED_STATEMENT_TYPES:
        return {"status": "rejected", "reason": f"Only SELECT statements are permitted, got {statement_type}."}

    upper_sql = generated_sql.upper()
    for keyword in FORBIDDEN_KEYWORDS:
        if keyword in upper_sql:
            return {"status": "rejected", "reason": f"Forbidden keyword detected: {keyword}"}

    if "LIMIT" not in upper_sql:
        generated_sql = generated_sql.rstrip(";") + f" LIMIT {ROW_LIMIT};"

    try:
        # readonly_db_connection is a connection using a database role with SELECT-only grants,
        # not the application's full-access credential -- this is the real backstop
        result = readonly_db_connection.execute(generated_sql, timeout=10)
        return {"status": "success", "sql": generated_sql, "rows": result.fetchall()}
    except Exception as e:
        return {"status": "error", "sql": generated_sql, "error": str(e)}
